//! Trusted App edits and native Reset after checked default replacement.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
fn click(app:&mut App,node:usize){let r=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn textarea_default_value_actual_app_pristine_dirty_reset_paint_and_stable_neighbor(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-textarea-default-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}button{position:absolute;top:20px;width:130px;height:32px}#pristine{left:20px}#dirty{left:170px}#reset{left:320px}#check{left:470px}#area{position:absolute;left:20px;top:80px;width:180px;height:70px}#neighbor{position:absolute;left:220px;top:100px;width:160px;height:30px}#stable{position:absolute;left:420px;top:100px}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}</style><form id=form><textarea id=area name=q>Seed</textarea><input id=neighbor value=neighbor><button id=pristine type=button>New default</button><button id=dirty type=button>Dirty default</button><button id=reset type=reset>Reset</button><button id=check type=button>Check</button></form><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var x=document.getElementById('area'),events=0;x.oninput=function(e){if(!e.isTrusted)throw 'untrusted input';events++;};document.getElementById('pristine').onclick=function(e){if(!e.isTrusted)throw 'untrusted click';x.defaultValue='New\r\n😀';if(x.value!=='New\n😀'||x.defaultValue!=='New\r\n😀'||events)throw 'pristine default';};document.getElementById('dirty').onclick=function(e){x.defaultValue='Reset\r\n😀';if(!e.isTrusted||x.value!=='Q'||x.defaultValue!=='Reset\r\n😀'||events!==1)throw 'dirty default';};document.getElementById('check').onclick=function(e){if(!e.isTrusted||x.value!=='Reset\n😀'||x.textLength!==8||x.defaultValue!=='Reset\r\n😀'||events!==1)throw 'actual native reset default';document.getElementById('paint').className='done';document.title='Textarea default checked';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let area=node(&app,"area");let neighbor=node(&app,"neighbor");let pristine=node(&app,"pristine");let dirty=node(&app,"dirty");let reset=node(&app,"reset");let check=node(&app,"check");let stable=node(&app,"stable");let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let r=app.page.controls.iter().find(|r|r.node==area).unwrap();let area_rect=(r.x,r.y,r.width,r.height);let initial_scroll=app.scroll;let initial=app.draw();click(&mut app,pristine);assert_eq!(app.forms.controls[&area].value.text(),"New\n😀");assert!(!app.forms.controls[&area].dirty_value);let changed=app.draw();let r=app.page.controls.iter().find(|r|r.node==area).unwrap();assert_eq!((r.x,r.y,r.width,r.height),area_rect);assert_eq!(app.scroll,initial_scroll);let (left,top,right,bottom)=(r.x.max(0)as usize,(app.content_top()+r.y-app.scroll).max(0)as usize,(r.x+r.width).min(changed.width as i32)as usize,(app.content_top()+r.y-app.scroll+r.height).min(changed.height as i32)as usize);assert!(left<right&&top<bottom);assert!((top..bottom).any(|y|initial.pixels[y*initial.width+left..y*initial.width+right]!=changed.pixels[y*changed.width+left..y*changed.width+right]),"actual editor paint changes at {:?}",area_rect);click(&mut app,area);app.key(0x41,true,false,false);app.text_input('Q');assert!(app.forms.controls[&area].dirty_value);click(&mut app,dirty);assert_eq!(app.forms.controls[&area].value.text(),"Q");click(&mut app,reset);assert_eq!(app.forms.controls[&area].value.text(),"Reset\n😀");assert!(!app.forms.controls[&area].dirty_value);
 app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}click(&mut app,check);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Textarea default checked");let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+170)as usize*painted.width+430],0xcc2244);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw,location,epoch));
}
